var i=`1427-taro-with-coconut-milk`;var n=`world-1427`;var o=`PW`;var a=`oceania`;var r=4;var l=57;var u={en:`Taro with Coconut Milk`,ua:`Таро з кокосовим молоком`};var s={en:`Palauan taro cooked until soft and covered in coconut milk.`,ua:`Палауське таро, повністю відварене до м’якості й подане з кокосовим молоком.`};var m=[{en:`Peel edible taro, rinse and cut into evenly sized pieces.`,ua:`Очистіть харчове таро, промийте й наріжте однаковими шматками.`,t:[`peeling`],m:10,i:[[`taro-root`,850,`g`]]},{en:`Boil taro in plenty of water 30–40 minutes until no hard core remains. Drain and discard water.`,ua:`Варіть таро у великій кількості води 30–40 хвилин до повного розм’якшення. Злийте воду.`,t:[`boiling`,`draining`],m:40,i:[[`water`,1700,`ml`]]},{en:`Heat coconut milk with salt until steaming, then gently simmer for about 5 minutes.`,ua:`Нагрійте кокосове молоко із сіллю до появи пари й томіть приблизно 5 хвилин.`,t:[`gentle-simmering`],m:5,i:[[`coconut-milk`,370,`ml`],[`sea-salt`,4,`g`]]},{en:`Serve hot taro with coconut milk spooned generously over it.`,ua:`Подавайте гаряче таро, щедро поливши кокосовим молоком.`,t:[`garnishing`],m:2,i:[]}];var c={slug:i,id:n,country:`PW`,region:a,servings:4,minutes:57,title:u,text:s,steps:m};export{o as country,c as default,n as id,l as minutes,a as region,r as servings,i as slug,m as steps,s as text,u as title};